result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "spicelet/netlist.py", "content": """"Netlist parsing for spicelet.

Grammar (case-insensitive keywords; one element per line):

    R/V/I/C name n1 n2 value     e.g.  R1 in out 1k
    .op
    .tran dt tstop               e.g.  .tran 1u 100u
    .ic node value               e.g.  .ic out 5

Lines starting with '*' are comments; blank lines are ignored.
Node '0' is the ground reference.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Dict, List, Optional


class SpiceletError(Exception):
    """Base class for all spicelet errors."""


class NetlistError(SpiceletError):
    """A malformed netlist. Carries the offending 1-based line number."""

    def __init__(self, line_no: int, message: str):
        self.line_no = line_no
        self.message = message
        super().__init__(f"line {line_no}: {message}")


class AnalysisError(SpiceletError):
    """The netlist parsed fine but cannot be solved."""


@dataclass(frozen=True)
class Element:
    kind: str          # 'R', 'V', 'I' or 'C'
    name: str
    n1: str
    n2: str
    value: float
    line_no: int       # source line, for error reporting


@dataclass
class Netlist:
    elements: List[Element] = field(default_factory=list)
    op: bool = False
    tran: Optional[tuple] = None          # (dt, tstop)
    ic: Dict[str, float] = field(default_factory=dict)

    @property
    def capacitors(self) -> List[Element]:
        return [e for e in self.elements if e.kind == "C"]

    def node_order(self) -> List[str]:
        """All non-ground nodes in order of first appearance."""
        seen: List[str] = []
        for e in self.elements:
            for n in (e.n1, e.n2):
                if n != "0" and n not in seen:
                    seen.append(n)
        for n in self.ic:
            if n != "0" and n not in seen:
                seen.append(n)
        return seen


_VALUE_RE = re.compile(
    r"^([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)\s*([A-Za-z]*)$"
)

# Longest prefixes must be checked first ('meg' before 'm').
_SUFFIXES = [
    ("meg", 1e6),
    ("mil", 25.4e-6),
    ("t", 1e12),
    ("g", 1e9),
    ("k", 1e3),
    ("m", 1e-3),
    ("u", 1e-6),
    ("n", 1e-9),
    ("p", 1e-12),
    ("f", 1e-15),
]


def parse_value(text: str, line_no: int) -> float:
    """Parse a SPICE-style value like '10k', '4.7u', '1meg', '2.2e3'."""
    m = _VALUE_RE.match(text.strip())
    if not m:
        raise NetlistError(line_no, f"invalid value {text!r}")
    number = float(m.group(1))
    suffix = m.group(2).lower()
    if suffix:
        for prefix, factor in _SUFFIXES:
            if suffix.startswith(prefix):
                return number * factor
        raise NetlistError(line_no, f"unknown unit suffix {text!r}")
    return number


def parse_netlist(text: str) -> Netlist:
    """Parse netlist text into a Netlist. Raises NetlistError with line numbers."""
    net = Netlist()
    for line_no, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("*"):
            continue

        fields = line.split()
        head = fields[0].lower()

        if head.startswith("."):
            directive = head
            args = fields[1:]
            if directive == ".op":
                if args:
                    raise NetlistError(line_no, ".op takes no arguments")
                net.op = True
            elif directive == ".tran":
                if len(args) != 2:
                    raise NetlistError(
                        line_no, ".tran expects: .tran dt tstop"
                    )
                try:
                    dt = parse_value(args[0], line_no)
                    tstop = parse_value(args[1], line_no)
                except NetlistError:
                    raise
                if dt <= 0 or tstop <= 0:
                    raise NetlistError(
                        line_no, ".tran dt and tstop must be positive"
                    )
                if dt > tstop:
                    raise NetlistError(
                        line_no, ".tran dt must not exceed tstop"
                    )
                net.tran = (dt, tstop)
            elif directive == ".ic":
                if len(args) != 2:
                    raise NetlistError(
                        line_no, ".ic expects: .ic node value"
                    )
                net.ic[args[0]] = parse_value(args[1], line_no)
            else:
                raise NetlistError(
                    line_no,
                    f"unknown directive {fields[0]!r} "
                    "(expected .op, .tran or .ic)",
                )
            continue

        # Element line: <kind><name> n1 n2 value
        if len(fields) != 4:
            raise NetlistError(
                line_no,
                "element lines must be: KIND name n1 n2 value",
            )

        designation, n1, n2, value_text = fields
        kind = designation[0].upper()

        if len(designation) < 2:
            raise NetlistError(line_no, f"missing element name {designation!r}")

        if kind == "R" and parse_value(value_text, line_no) <= 0:
            raise NetlistError(line_no, f"resistor {designation!r} needs a positive value")
        if kind not in ("R", "V", "I", "C"):
            raise NetlistError(
                line_no,
                f"unknown element type {designation!r} (expected R, V, I or C)",
            )

        net.elements.append(
            Element(
                kind=kind,
                name=designation,
                n1=n1,
                n2=n2,
                value=parse_value(value_text, line_no),
                line_no=line_no,
            )
        )

    if net.tran is not None:
        pass  # .tran implies transient mode at the CLI level
    return net
