result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "spicelet/mna.py", "content": """"Modified Nodal Analysis (MNA) solver for spicelet.

Unknown vector: [node voltages (ground excluded), voltage-source branch currents].

Sign conventions:
  * V source Vxxx n+ n- E drives n+ above n-; its branch current `i`
    is positive flowing through the source from n+ to n-.
  * I source Ixxx n1 n2 value pushes `value` amps from n1 through the
    source out at n2.
  * Element currents are positive flowing from n1 into the element.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

import numpy as np

from .netlist import AnalysisError, Element, Netlist


class _System:
    """Mutable MNA system being stamped."""

    def __init__(self, node_index: Dict[str, int], num_sources: int):
        self.node_index = node_index          # node name -> row (0-based)
        self.n_nodes = len(node_index)
        self.num_sources = num_sources
        size = self.n_nodes + num_sources
        self.A = np.zeros((size, size))
        self.z = np.zeros(size)

    def row(self, node: str) -> Optional[int]:
        """Row for a node, or None for ground."""
        return self.node_index.get(node)

    def solve(self) -> np.ndarray:
        try:
            return np.linalg.solve(self.A, self.z)
        except np.linalg.LinAlgError:
            raise AnalysisError(
                "singular system matrix — check for floating nodes "
                "(nodes with no DC path to ground) or shorted sources"
            )


def _node_map(netlist: Netlist, extra_source_nodes: List[Tuple[str, str]]) -> Dict[str, int]:
    names = netlist.node_order()
    return {name: i for i, name in enumerate(names)}


def _stamp_resistor(sys: _System, e: Element) -> None:
    g = 1.0 / e.value
    r1, r2 = sys.row(e.n1), sys.row(e.n2)
    if r1 is not None:
        sys.A[r1, r1] += g
        if r2 is not None:
            sys.A[r1, r2] -= g
            sys.A[r2, r1] -= g
    if r2 is not None:
        sys.A[r2, r2] += g


def _stamp_isource(sys: _System, e: Element) -> None:
    """Current source pushing e.value A from n1 through itself out at n2."""
    r1, r2 = sys.row(e.n1), sys.row(e.n2)
    if r1 is not None:
        sys.z[r1] -= e.value
    if r2 is not None:
        sys.z[r2] += e.value


def _stamp_vsource(sys: _System, e: Element, col: int) -> None:
    """Voltage source in column `col` of the source block."""
    r1, r2 = sys.row(e.n1), sys.row(e.n2)
    if r1 is not None:
        sys.A[r1, col] += 1.0
        sys.A[col, r1] += 1.0
    if r2 is not None:
        sys.A[r2, col] -= 1.0
        sys.A[col, r2] -= 1.0
    sys.z[col] = e.value


def dc_operating_point(netlist: Netlist) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Solve .op with capacitors open.

    Returns (node_voltages, vsource_currents) keyed by element/node name.
    """
    vsources = [e for e in netlist.elements if e.kind == "V"]
    node_index = _node_map(netlist, [])
    sys_ = _System(node_index, len(vsources))

    for e in netlist.elements:
        if e.kind == "R":
            _stamp_resistor(sys_, e)
        elif e.kind == "I":
            _stamp_isource(sys_, e)
        elif e.kind == "V":
            _stamp_vsource(sys_, e, sys_.n_nodes + vsources.index(e))
        # C: open circuit at DC -> nothing

    x = sys_.solve()
    inv = {v: k for k, v in node_index.items()}
    voltages = {inv[r]: float(x[r]) for r in range(sys_.n_nodes)}
    currents = {e.name: float(x[sys_.n_nodes + i]) for i, e in enumerate(vsources)}
    return voltages, currents


def initial_state(netlist: Netlist) -> Tuple[List[float], List[float]]:
    """Consistent initial state for transient analysis.

    Returns (capacitor_voltages, capacitor_currents) aligned with
    ``netlist.capacitors``:

      1. Node voltages at t=0 come from a DC solve (caps open), overridden
         by any '.ic node value' directives.
      2. Each capacitor's initial voltage is the difference of those node
         voltages.
      3. Capacitors are then replaced by ideal voltage sources holding
         those voltages and the DC system re-solved; the resulting branch
         currents are the physically consistent i_C(0+).
    """
    caps = netlist.capacitors
    if not caps:
        return [], []

    base, _ = dc_operating_point(netlist)
    node_v = dict(base)
    for node, value in netlist.ic.items():
        node_v[node] = value

    cap_volts = [
        node_v.get(c.n1, 0.0) - node_v.get(c.n2, 0.0) for c in caps
    ]

    # Re-solve with each capacitor replaced by a voltage source of value
    # v_C(0); its branch current equals i_C(0+) with our sign convention
    # (positive flowing from n1 into the capacitor).
    vsources = [e for e in netlist.elements if e.kind == "V"]
    node_index = _node_map(netlist, [])
    sys_ = _System(node_index, len(vsources) + len(caps))
    all_vsources = list(vsources) + caps

    for e in netlist.elements:
        if e.kind == "R":
            _stamp_resistor(sys_, e)
        elif e.kind == "I":
            _stamp_isource(sys_, e)
        elif e.kind == "V":
            _stamp_vsource(sys_, e, sys_.n_nodes + all_vsources.index(e))

    for i, c in enumerate(caps):
        _stamp_vsource(sys_, c, sys_.n_nodes + len(vsources) + i)
        sys_.z[sys_.n_nodes + len(vsources) + i] = cap_volts[i]

    x = sys_.solve()
    cap_currents = [
        float(x[sys_.n_nodes + len(vsources) + i]) for i in range(len(caps))
    ]
    return cap_volts, cap_currents
