result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "spicelet/transient.py", "content": """"Transient analysis for spicelet via trapezoidal integration.

Capacitors use the trapezoidal companion model. For a capacitor C
between nodes a and b with previous state (v_n = v_ab, i_n flowing from
a into the capacitor), the backward relation over a step h is

    v_{n+1} - v_n = (h / 2C) * (i_{n+1} + i_n)

which rearranges to a conductance in parallel with a current source:

    i_{n+1} = geq * v_{n+1} - Ieq,   geq = 2C/h,   Ieq = geq*v_n + i_n

Ieq is stamped as an injection into node a (and out of node b).
"""

from __future__ import annotations

from typing import Dict, List, Tuple

import numpy as np

from .mna import _stamp_isource, _stamp_resistor, _stamp_vsource, _System, _node_map, initial_state
from .netlist import AnalysisError, Element, Netlist


def _stamp_capacitor_companion(sys: _System, cap: Element, geq: float, ieq: float) -> None:
    _stamp_resistor_value(sys, cap.n1, cap.n2, geq)
    r1, r2 = sys.row(cap.n1), sys.row(cap.n2)
    if r1 is not None:
        sys.z[r1] += ieq
    if r2 is not None:
        sys.z[r2] -= ieq


def _stamp_resistor_value(sys: _System, n1: str, n2: str, g: float) -> None:
    r1, r2 = sys.row(n1), sys.row(n2)
    if r1 is not None:
        sys.A[r1, r1] += g
        if r2 is not None:
            sys.A[r1, r2] -= g
            sys.A[r2, r1] -= g
    if r2 is not None:
        sys.A[r2, r2] += g


class TransientResult:
    def __init__(self, times: List[float], voltages: Dict[str, List[float]]):
        self.times = times
        self.voltages = voltages

    @property
    def nodes(self) -> List[str]:
        return list(self.voltages.keys())


def run_transient(netlist: Netlist) -> TransientResult:
    dt, tstop = netlist.tran  # type: ignore[misc]
    caps = netlist.capacitors
    nodes = netlist.node_order()

    cap_volts, cap_currents = initial_state(netlist)
    v_prev = list(cap_volts)
    i_prev = list(cap_currents)

    vsources = [e for e in netlist.elements if e.kind == "V"]
    isources = [e for e in netlist.elements if e.kind == "I"]
    resistors = [e for e in netlist.elements if e.kind == "R"]

    times: List[float] = [0.0]
    columns: Dict[str, List[float]] = {n: [] for n in nodes}
    for c, v0 in zip(caps, v_prev):
        pass
    _record(times[-1], netlist, caps, v_prev, columns, nodes)

    geq = np.array([2.0 * c.value / dt for c in caps]) if caps else []

    t = 0.0
    while t < tstop - 1e-12:
        h = min(dt, tstop - t)
        # Recompute geq for the (possibly shortened) final step.
        geq_h = np.array([2.0 * c.value / h for c in caps]) if caps else []

        node_index = _node_map(netlist, [])
        sys_ = _System(node_index, len(vsources))

        for e in resistors:
            _stamp_resistor(sys_, e)
        for e in vsources:
            _stamp_vsource(sys_, e, sys_.n_nodes + vsources.index(e))
        for e in isources:
            _stamp_isource(sys_, e)
        for k, c in enumerate(caps):
            ieq = geq_h[k] * v_prev[k] + i_prev[k]
            _stamp_capacitor_companion(sys_, c, float(geq_h[k]), ieq)

        x = sys_.solve()
        inv = {v: kk for kk, v in node_index.items()}
        node_v = {inv[r]: float(x[r]) for r in range(sys_.n_nodes)}

        # Update capacitor states: v_{n+1} and the true branch current.
        for k, c in enumerate(caps):
            v_new = node_v.get(c.n1, 0.0) - node_v.get(c.n2, 0.0)
            ieq_k = geq_h[k] * v_prev[k] + i_prev[k]
            i_new = geq_h[k] * v_new - ieq_k
            v_prev[k] = v_new
            i_prev[k] = float(i_new)

        t += h
        times.append(t)
        _record(t, netlist, caps, v_prev, columns, nodes)

    return TransientResult(times, columns)


def _record(
    t: float,
    netlist: Netlist,
    caps: List[Element],
    v_prev: List[float],
    columns: Dict[str, List[float]],
    nodes: List[str],
) -> None:
    """Record one time point; capacitor terminal voltages come from their state."""
    cap_node_v: Dict[str, float] = {}
    for c, v in zip(caps, v_prev):
        if c.n1 != "0":
            cap_node_v[c.n1] = v + (cap_node_v.get(c.n2, 0.0))
        if c.n2 != "0":
            cap_node_v[c.n2] = (cap_node_v.get(c.n1, 0.0)) - v
    for n in nodes:
        if n in cap_node_v:
            columns[n].append(cap_node_v[n])
        else:
            # Non-capacitor-anchored nodes are filled during stepping;
            # at t=0 they fall back to the DC-with-.ic solution.
            columns[n].append(float("nan"))
